const event = $('When Called').first().json;
const locale = ['en', 'pl', 'ru', 'uk'].includes(event.ui_language) ? event.ui_language : 'pl';
const input = String(event.search_query || '').trim();
const fallbackLocation = String($env.JOB_LOCATION || 'Warszawa').trim();
const separator = input.lastIndexOf('|');
const query = separator < 0 ? input : input.slice(0, separator).trim();
const location = (separator < 0 ? fallbackLocation : input.slice(separator + 1).trim()) || fallbackLocation;
const esc = value => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;');
const copy = {
  en: { usage: 'Usage: /search <keywords> [| <city>]', tooLong: 'Keep keywords under 120 characters and city under 80 characters.', local: 'Search locally in', remote: 'Also search remote vacancies', note: 'The city defaults to JOB_LOCATION. Remote links use the keywords “remote” and “praca zdalna”; refine with each site’s filters. These links open official search pages only; the bot does not download listings. Add a chosen vacancy with /add <URL>.' },
  pl: { usage: 'Użycie: /search <słowa kluczowe> [| <miasto>]', tooLong: 'Fraza może mieć maks. 120 znaków, a miasto 80 znaków.', local: 'Szukaj ofert w okolicy', remote: 'Szukaj także ofert zdalnych', note: 'Domyślne miasto jest ustawiane przez JOB_LOCATION. Linki zdalne używają fraz „remote” i „praca zdalna”; doprecyzuj filtry na stronie. Linki otwierają wyłącznie oficjalne wyszukiwarki; bot nie pobiera ofert. Wybraną ofertę dodaj przez /add <URL>.' },
  ru: { usage: 'Использование: /search <ключевые слова> [| <город>]', tooLong: 'Запрос должен быть короче 120 символов, город — 80 символов.', local: 'Поиск вакансий в городе', remote: 'Также поиск удалённых вакансий', note: 'Город по умолчанию задаёт JOB_LOCATION. Для удалённого поиска используются слова «remote» и «praca zdalna»; уточните фильтры на сайте. Ссылки открывают только официальные страницы поиска; бот не скачивает объявления. Добавьте вакансию командой /add <URL>.' },
  uk: { usage: 'Використання: /search <ключові слова> [| <місто>]', tooLong: 'Запит має бути до 120 символів, місто — до 80 символів.', local: 'Пошук вакансій у місті', remote: 'Також пошук віддалених вакансій', note: 'Місто за замовчуванням задає JOB_LOCATION. Для віддаленого пошуку використовуються слова «remote» і «praca zdalna»; уточни фільтри на сайті. Посилання відкривають лише офіційні сторінки пошуку; бот не завантажує оголошення. Додай вакансію командою /add <URL>.' }
};
if (!query) return {json: {chat_id: event.chat_id, text: copy[locale].usage}};
if (query.length > 120 || location.length > 80) return {json: {chat_id: event.chat_id, text: copy[locale].tooLong}};
const slug = location.toLowerCase().replace(/ł/g, 'l').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const keyword = encodeURIComponent(query);
const localLinks = [
  ['Pracuj.pl', `https://www.pracuj.pl/praca/${slug};wp?kw=${keyword}`],
  ['JustJoin.it', `https://justjoin.it/job-offers/${slug}?keyword=${keyword}`],
  ['OLX Praca', `https://www.olx.pl/praca/${slug}/q-${keyword}/`],
  ['LinkedIn', `https://www.linkedin.com/jobs/search/?keywords=${keyword}&location=${encodeURIComponent(location)}`]
];
const remoteLinks = [];
for (const term of ['remote', 'praca zdalna']) {
  const remoteKeyword = encodeURIComponent(`${query} ${term}`);
  remoteLinks.push(
    [`Pracuj.pl — ${term}`, `https://www.pracuj.pl/praca?kw=${remoteKeyword}`],
    [`JustJoin.it — ${term}`, `https://justjoin.it/job-offers?keyword=${remoteKeyword}`],
    [`OLX Praca — ${term}`, `https://www.olx.pl/praca/q-${remoteKeyword}/`],
    [`LinkedIn — ${term}`, `https://www.linkedin.com/jobs/search/?keywords=${remoteKeyword}&location=Poland`]
  );
}
const renderLinks = links => links.map(([name, url]) => `• <a href=\"${url.replace(/&/g, '&amp;')}\">${esc(name)}</a>`).join('\n');
const text = `🔎 <b>${copy[locale].local} ${esc(location)} — ${esc(query)}</b>\n${renderLinks(localLinks)}\n\n🌐 <b>${copy[locale].remote} — ${esc(query)}</b>\n${renderLinks(remoteLinks)}\n\n${copy[locale].note}`;
return {json: {chat_id: event.chat_id, text}};
